-- Schemat bazy nowej aplikacji.
-- SQLite w pamieci (Microsoft.Data.Sqlite, Database:Name), ladowany przy starcie przez DatabaseInitializer.
-- Dialekt: id z autonumeracja = INTEGER PRIMARY KEY AUTOINCREMENT (w H2: GENERATED BY DEFAULT AS IDENTITY);
-- daty i czasy jako tekst yyyy-MM-dd HH:mm:ss (porownania zakresow ida tekstowo).
-- Odpowiedniki legacy: legacy-app-parent/legacy-app/Database/01_schema.sql
--   Klienci :28-42, Sprzet :46-56, Taryfy :62-69, Rezerwacje :73-85, Wypozyczenia :92-108.
-- Swiadomie pominiete (poza zakresem nowej aplikacji): Faktury, PozycjeFaktur, DziennikOperacji,
-- kolumny kontaktowe klienta (Email, Telefon, NumerDokumentu, NIP) - minimalizacja danych.
-- Statusy jako nazwy enumow modelu (mapowanie na kody legacy w komentarzach i w enumach modelu).

DROP TABLE IF EXISTS rentals;
DROP TABLE IF EXISTS reservations;
DROP TABLE IF EXISTS tariffs;
DROP TABLE IF EXISTS equipment;
DROP TABLE IF EXISTS customers;

-- Klienci (01_schema.sql:28-42); discount_tier = ProgRabatu (0..3 po przycieciu, CustomerManager.vb:46-49)
CREATE TABLE customers (
    id             BIGINT        PRIMARY KEY,
    first_name     VARCHAR(50)   NOT NULL,
    last_name      VARCHAR(80)   NOT NULL,
    company_name   VARCHAR(120),
    discount_tier  INT           NOT NULL DEFAULT 0,
    blocked        BOOLEAN       NOT NULL DEFAULT FALSE,
    block_reason   VARCHAR(200)
);

-- Sprzet (01_schema.sql:46-56); status: AVAILABLE=D, RENTED=W, SERVICE=S, RETIRED=X
CREATE TABLE equipment (
    id                BIGINT         PRIMARY KEY,
    inventory_number  VARCHAR(20)    NOT NULL UNIQUE,
    name              VARCHAR(100)   NOT NULL,
    category          CHAR(3)        NOT NULL,
    daily_rate        DECIMAL(10,2)  NOT NULL,
    deposit           DECIMAL(10,2)  NOT NULL,
    status            VARCHAR(10)    NOT NULL DEFAULT 'AVAILABLE'
);

-- Taryfy (01_schema.sql:62-69); obowiazuje najnowsza z valid_from <= dzien wydania (02_procedury.sql:281-290)
CREATE TABLE tariffs (
    id                       BIGINT        PRIMARY KEY,
    category                 CHAR(3)       NOT NULL,
    weekend_multiplier       DECIMAL(4,2)  NOT NULL,
    weekly_discount_percent  DECIMAL(5,2)  NOT NULL,
    valid_from               DATE          NOT NULL,
    CONSTRAINT uq_tariffs_category_from UNIQUE (category, valid_from)
);

-- Rezerwacje (01_schema.sql:73-85); status: NEW=N, CONFIRMED=P, CANCELLED=A, COMPLETED=Z
-- date_from/date_to zamiast from/to (slowa zastrzezone SQL)
CREATE TABLE reservations (
    id               INTEGER PRIMARY KEY AUTOINCREMENT,
    customer_id      BIGINT         NOT NULL REFERENCES customers(id),
    equipment_id     BIGINT         NOT NULL REFERENCES equipment(id),
    date_from        TIMESTAMP      NOT NULL,
    date_to          TIMESTAMP      NOT NULL,
    status           VARCHAR(10)    NOT NULL DEFAULT 'NEW',
    estimated_price  DECIMAL(10,2)  NOT NULL,
    notes            VARCHAR(500),
    created_at       TIMESTAMP      NOT NULL
);

CREATE INDEX ix_reservations_equipment ON reservations (equipment_id, date_from, date_to);

-- Wypozyczenia (01_schema.sql:92-108); status: OPEN=O, CLOSED=Z
CREATE TABLE rentals (
    id                INTEGER PRIMARY KEY AUTOINCREMENT,
    reservation_id    BIGINT         REFERENCES reservations(id),
    customer_id       BIGINT         NOT NULL REFERENCES customers(id),
    equipment_id      BIGINT         NOT NULL REFERENCES equipment(id),
    issued_at         TIMESTAMP      NOT NULL,
    planned_return    TIMESTAMP      NOT NULL,
    returned_at       TIMESTAMP,
    deposit_taken     DECIMAL(10,2)  NOT NULL,
    fee               DECIMAL(10,2),
    penalty           DECIMAL(10,2),
    deposit_returned  DECIMAL(10,2),
    status            VARCHAR(10)    NOT NULL DEFAULT 'OPEN'
);

CREATE INDEX ix_rentals_status ON rentals (status, equipment_id);
